// Color Chrome Effect (STRONG) fitted to 15 aligned OFF/STRONG comparisons
// across Fujifilm official samples, Hirophotalk, Iwa-maru and Mountainview Japan.
const colorChromeCoefficients = [
  [-46.59, -65.29, -37.08],
  [27.25, 60.80, -6.66],
  [45.29, 57.65, 37.63],
  [-65.15, -15.29, 48.89],
  [48.99, -29.36, -38.66],
  [-38.07, 32.19, -62.15],
  [88.18, -19.39, 111.73],
  [32.70, 9.42, -53.48],
  [50.12, -10.17, 54.71],
];

function colorEffectDelta([red, green, blue]) {
  const spread = Math.max(red, green, blue) - Math.min(red, green, blue);
  // A one-cell neutral margin prevents interpolation from tinting gray pixels.
  const neutralWeight = Math.min(1, Math.max(0, (spread - 1 / COLOR_GRID_STEPS) * 12));
  const colorWeight = Math.max(0, Math.max(red, green) - blue) * neutralWeight;
  if (colorWeight === 0) return [0, 0, 0];
  const luma = 0.2126 * red + 0.7152 * green + 0.0722 * blue;
  const rg = red - green;
  const w2 = colorWeight * spread;
  const absRg = Math.sqrt(rg * rg + 0.01) - 0.1;
  const features = [
    colorWeight,
    colorWeight * luma,
    colorWeight * luma * luma,
    w2,
    w2 * luma,
    colorWeight * rg,
    colorWeight * rg * luma,
    colorWeight * absRg,
    colorWeight * absRg * luma,
  ];
  return [0, 1, 2].map(channel =>
    colorChromeCoefficients.reduce((sum, coef, i) => sum + features[i] * coef[channel], 0)
  );
}


function createFilmPreset(suffix, { tone, chroma }, getDelta = filmColorDelta) {
  return createPreset(suffix, rgb => getDelta(rgb, tone, chroma));
}

